 71→}
 72→
 73→func marshalPromptContent(prompt string) json.RawMessage {
 74→	content, _ := json.Marshal(map[string]interface{}{
 75→		"Prompt": map[string]string{"prompt": prompt},
 76→	})
 77→	return content
 78→}
