 80→// AddPrompt adds a user prompt entry with no assistant response.
 81→func (kt *KiroTranscript) AddPrompt(prompt string) *KiroTranscript {
 82→	kt.History = append(kt.History, kiroHistoryEntry{
 83→		User: kiroUserMessage{Content: marshalPromptContent(prompt)},
 84→	})
 85→	return kt
 86→}
