 88→// AddPromptWithFileEdit adds a user prompt paired with an assistant response that contains a file edit tool use.
 89→func (kt *KiroTranscript) AddPromptWithFileEdit(prompt, filePath string) *KiroTranscript {
 90→	toolUse := map[string]interface{}{
 91→		"ToolUse": map[string]interface{}{
 92→			"message_id": "msg-001",
 93→			"tool_uses": []map[string]interface{}{
 94→				{
 95→					"id":   "tool-001",
 96→					"name": "fs_write",
 97→					"args": map[string]string{"path": filePath},
 98→				},
 99→			},
100→		},
101→	}
102→	assistantContent, _ := json.Marshal(toolUse)
103→
104→	kt.History = append(kt.History, kiroHistoryEntry{
105→		User:      kiroUserMessage{Content: marshalPromptContent(prompt)},
106→		Assistant: assistantContent,
107→	})
108→	return kt
109→}
110→
111→// AddResponse adds a user prompt paired with an assistant text response.
112→func (kt *KiroTranscript) AddResponse(prompt, response string) *KiroTranscript {
113→	userContent := marshalPromptContent(prompt)
114→
115→	responseContent := map[string]interface{}{
116→		"Response": map[string]interface{}{
117→			"message_id": "msg-resp",
118→			"content":    response,
119→		},
120→	}
121→	assistantContent, _ := json.Marshal(responseContent)
122→
123→	kt.History = append(kt.History, kiroHistoryEntry{
124→		User:      kiroUserMessage{Content: userContent},
125→		Assistant: assistantContent,
126→	})
127→	return kt
128→}
